"""Value-DAG helpers for the V9 pipeline."""

import json

from .common import arithmetic


def extract(row, program):
    """DAG of *first occurrences* of values generated by a replayed program.

    Starting values are seed nodes.  A value produced again later keeps the
    first production, which is the dependency graph the frozen Stage 2 scheduler
    searches over.  The program is generated in the current call; no archived
    answer is involved.
    """
    starting = json.loads(row['starting_values'])
    registers = dict(enumerate(starting))
    seen = set(starting)
    graph = {}
    for op, left, right, destination in program:
        a, b = registers[left], registers[right]
        value = arithmetic(op, a, b)
        registers[destination] = value
        if value not in seen:
            graph[value] = (op, a, b)
            seen.add(value)
    return graph
